import fs from 'node:fs/promises';
const endpoint='https://mondayid-host.vercel.app/api/mcp';
async function rpc(id,method,params={}){
  const r=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json','accept':'application/json','MCP-Protocol-Version':'2025-03-26'},body:JSON.stringify({jsonrpc:'2.0',id,method,params})});
  const text=await r.text();
  let json; try{json=JSON.parse(text)}catch{json={parseError:true,text}}
  return {status:r.status,contentType:r.headers.get('content-type'),json};
}
const init=await rpc(1,'initialize',{protocolVersion:'2025-03-26',capabilities:{},clientInfo:{name:'mondayid-computer-proof',version:'1.0.0'}});
const list=await rpc(2,'tools/list',{});
const health=await rpc(3,'tools/call',{name:'health',arguments:{}});
const names=list?.json?.result?.tools?.map(x=>x.name)||[];
const ok=init.status===200 && init?.json?.result?.serverInfo?.name==='monday-work' && names.includes('health') && names.includes('capability_manifest') && names.includes('get_state') && health.status===200 && health?.json?.result?.structuredContent?.generation===5;
const proof={ok,marker:ok?'monday-work-mcp-live-ok':'monday-work-mcp-live-fail',endpoint,init,list,health};
await fs.writeFile('monday-work-mcp-live.json',JSON.stringify(proof));
console.log(JSON.stringify(proof));
if(!ok) process.exitCode=2;
